function validate([s, target]) {
  if (typeof s !== 'string' || typeof target !== 'string') return 's and target must be strings.';
  if (s.length !== target.length) return 's and target must have the same length.';
  if (s.length < 2 || s.length > 100000) return 'The strings need 2 to 10^5 characters.';
  if (!/^[01]+$/.test(s) || !/^[01]+$/.test(target)) return "Use only the characters '0' and '1'.";
  return null;
}

