function makeStringsEqual(s, target) {
  // Breadth-first search over every string reachable from s.
  const n = s.length;
  const seen = new Set([s]);
  const queue = [s];
  for (let head = 0; head < queue.length; head++) {
    const cur = queue[head];
    if (cur === target) return true;
    for (let i = 0; i < n; i++)
      for (let j = 0; j < n; j++) {
        if (i === j) continue;
        const a = Number(cur[i]), b = Number(cur[j]);
        const next = cur.split('');
        next[i] = String(a | b);
        next[j] = String(a ^ b);
        const key = next.join('');
        if (!seen.has(key)) { seen.add(key); queue.push(key); }
      }
  }
  return false;
}

