function generate(rand, size) {
  const n = size === 'large' ? 8000 + Math.floor(rand() * 2001) : 2 + Math.floor(rand() * 7);
  // Each string is all zeros, a single one, or random bits, so every reachable/unreachable mix appears.
  const make = () => {
    const shape = rand();
    if (shape < 0.3) return '0'.repeat(n);
    if (shape < 0.45) { const at = Math.floor(rand() * n); return '0'.repeat(at) + '1' + '0'.repeat(n - at - 1); }
    const density = rand();
    return Array.from({ length: n }, () => (rand() < density ? '1' : '0')).join('');
  };
  return [make(), make()];
}
